import {createGame,people,factions,roads,actor,owned,order,setPolicy,interact,march,advance,resolve,restore,succeed} from './engine.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.floor(n).toLocaleString('ko-KR');
const KEY='three-kingdom.save.v1';let state=null,tab='천하',selected=0,saveError='',toastTimer;
try{const raw=localStorage.getItem(KEY);if(raw)state=restore(raw);}catch{saveError='저장을 읽지 못했습니다. 새 게임 시작 전에 저장 파일을 확인하세요.';}
const icons=[`<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16"/>`,`<path d="M3 21h18M5 21V8l7-5 7 5v13M9 21v-7h6v7M9 9h6"/>`,`<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>`,`<path d="M5 3h14v18H5zM8 7h8M8 11h8M8 15h5"/>`,`<path d="M4 5h16M4 12h16M4 19h16"/><circle cx="8" cy="5" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="9" cy="19" r="2"/>`];
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saveError='';}catch{saveError='기기 저장에 실패했습니다. 더 보기에서 저장 파일을 내보내세요.';toast(saveError);}}
function date(day){const d=new Date(Date.UTC(184,2,1+day));return `184년 ${d.getUTCMonth()+1}월 ${d.getUTCDate()}일`;}
function logs(n=5){return state.logs.slice(0,n).map(l=>`<div class="list-item"><div class="log-date">${date(l.day)}</div><div class="log-text">${esc(l.text)}</div></div>`).join('');}
function start(){return `<div class="start"><div class="eyebrow">THREE KINGDOM · 184</div><h1>황건의 봄</h1><p class="intro">무너지는 질서, 일어서는 영웅들.<br>당신의 선택이 한 사람의 삶과<br>천하의 흐름을 바꿉니다.</p><div class="hero-line"><span>사람을 얻고</span><span>때를 기다려</span><span>천하로 나아가다</span></div><div class="kicker">첫 번째 여정</div><h2>어떤 인물로 시작할까요?</h2><label for="player">역사 인물 · 초기 개발판 8명</label><select id="player">${people.map(p=>`<option value="${p[0]}" ${p[0]==='liubei'?'selected':''}>${p[1]} · ${p[3]} · ${factions[p[2]]}</option>`).join('')}</select><button class="btn primary" data-action="start">184년으로 들어가기 →</button><p class="muted" style="margin-top:15px">하루씩 진행 · 자동 전투 · 기기 내부 저장<br>유료 API·계정 없이 작동합니다.</p><div class="notice">v0.1 개발 시험판. 도시 연결·인물 배치·능력치는 게임 흐름 확인용 각색입니다. 역사 고증과 전체 지도는 후속 개발 대상입니다.</div>${saveError?`<div class="notice">${esc(saveError)}</div><button class="btn" data-action="import">저장 파일 불러오기</button>`:''}</div>`;}
function map(){return `<div class="map-wrap"><svg class="map" viewBox="0 0 480 500" role="img" aria-label="중원 일부 도시 연결 지도. 후한 토벌군은 초록색, 황건군은 황갈색입니다."><path class="water" d="M-20 180 Q60 225 130 175 T260 208 T490 200M-20 415Q80 440 175 401T365 463T500 437"/><g class="mount"><path d="m17 112 18-26 20 26m-12 0 24-38 23 38m245 272 24-31 23 31m-8-5 17-26 22 26M20 309l18-28 16 28m-9 0 17-30 20 30"/></g>${roads.map(([a,b])=>`<line class="road" x1="${state.cities[a].x}" y1="${state.cities[a].y}" x2="${state.cities[b].x}" y2="${state.cities[b].y}"/>`).join('')}${state.armies.map(a=>{const f=state.cities[a.from],t=state.cities[a.to],v=1-a.days/a.total;return `<circle cx="${f.x+(t.x-f.x)*v}" cy="${f.y+(t.y-f.y)*v}" r="5" fill="#c8a048" stroke="#fff" stroke-width="2"/>`;}).join('')}${state.cities.map(c=>`<g class="node" role="button" tabindex="0" aria-label="${c.name}，${factions[c.faction]}，兵力${fmt(c.troops)}" data-city="${c.id}">${c.id===selected?`<circle class="ring" cx="${c.x}" cy="${c.y}" r="20"/>`:''}<circle cx="${c.x}" cy="${c.y}" r="12" fill="${c.faction===0?'#32594a':'#b77940'}" stroke="#f4f0e6" stroke-width="3"/><text x="${c.x}" y="${c.y+32}" text-anchor="middle">${c.name}</text></g>`).join('')}</svg><div class="legend"><span><i class="dot"></i>후한 토벌군</span><span><i class="dot enemy"></i>황건군</span><span>● 이동 부대</span></div></div>`;}
function cityCard(c,full=false){return `<div class="card"><div class="row"><h3>${c.name}</h3><span class="tag ${c.faction===1?'enemy':''}">${factions[c.faction]}</span></div><div class="stats"><div class="stat"><small>병력</small><strong>${fmt(c.troops)}</strong></div><div class="stat"><small>자금</small><strong>${fmt(c.gold)}</strong></div><div class="stat"><small>군량</small><strong>${fmt(c.food)}</strong></div></div>${full?`<div class="row muted" style="margin-top:15px"><span>농업 ${c.farm}</span><span>훈련 ${c.training}</span><span>사기 ${c.morale}</span></div>`:''}${c.task?`<div class="notice">${c.task.type} 수행 중 · ${c.task.left}일 남음</div>`:''}${!full?`<div class="row" style="margin-top:16px"><span class="muted">${owned(state,c.id)?'소속 세력 도시':'상대 세력 도시'}</span>${owned(state,c.id)?`<button class="btn small" data-action="manage">도시 관리 →</button>`:`<button class="btn small" data-action="campaign">출진 계획 →</button>`}</div>`:''}</div>`;}
function world(){const mine=state.cities.filter(c=>owned(state,c.id));return `<div class="eyebrow">THE WORLD</div><div class="section-title"><h2>천하의 흐름</h2><span class="muted">8개 도시 · 시험 지도</span></div><div class="objective"><strong>${actor(state).role==='장수'?'첫 목표 · 공적 30을 쌓아 태수로':'첫 목표 · 병력을 정비하고 적 도시를 공략'}</strong>${actor(state).role==='장수'?`내정 완료와 교류로 공적을 쌓으세요. 현재 ${actor(state).merit} / 30.`:`소속 도시 ${mine.length}개. 군량·훈련을 확인하고 연결된 적 도시로 출진하세요.`}</div>${map()}${cityCard(state.cities[selected])}<div class="section-title subhead"><h3>최근 소식</h3><button class="btn small" data-tab="기록">전체 기록</button></div><div class="card">${logs(3)}</div>`;}
function cities(){const c=state.cities[selected],mine=state.cities.filter(c=>owned(state,c.id));return `<div class="eyebrow">GOVERNANCE</div><div class="section-title"><h2>도시와 군정</h2><span class="muted">${actor(state).role==='장수'?'건의 가능한 명령':'직접 관리 · 위임'}</span></div><label for="city">관리할 도시</label><select class="city-select" id="city">${mine.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${c.name}</option>`).join('')}</select>${cityCard(c,true)}<div class="grid2">${[['개발','5일 · 자금 250'],['훈련','3일 · 자금 180'],['징병','4일 · 자금 500'],['군량','3일 · 자금 250']].map(([t,d])=>`<button class="btn" data-order="${t}" ${c.task||state.pending?'disabled':''}>${t}<br><small class="muted">${d}</small></button>`).join('')}</div><div class="card" style="margin-top:14px"><h3>도시 운영 위임</h3><p class="muted" style="margin:8px 0">농업: 매주 자금 80 → 농업 +2<br>군비: 매주 자금 100 → 병력 +200, 훈련 +1<br>균형: 자원 자동 수입만 유지</p>${actor(state).role==='장수'?'<p class="muted">태수로 승진하면 방침을 지정할 수 있습니다.</p>':`<label for="policy">현재 방침</label><select id="policy">${['균형','농업','군비'].map(p=>`<option ${c.order===p?'selected':''}>${p}</option>`).join('')}</select>`}</div><div class="section-title subhead"><h3>출진 계획</h3></div><div class="card"><p class="muted">선택한 도시와 직접 연결된 적 도시를 공략합니다. 지휘관은 현재 플레이어입니다. 부대는 도착한 날 전투를 치릅니다.</p>${campaign(c)}</div>${armies()}`;}
function campaign(c){const targets=state.cities.filter(t=>t.faction!==c.faction&&roads.some(r=>r.includes(t.id)&&r.includes(c.id)));if(!targets.length)return '<p class="empty">이 도시와 연결된 적 도시가 없습니다.</p>';return `<label for="target">목표 도시</label><select id="target">${targets.map(t=>`<option value="${t.id}">${t.name} · 수비병 ${fmt(t.troops)}</option>`).join('')}</select><label for="troops">출진 병력 · 수비병 1,000명 유지</label><input id="troops" type="number" min="1000" max="${Math.max(1000,c.troops-1000)}" step="500" value="${Math.max(1000,Math.min(4000,c.troops-1000))}"><div class="grid2"><div><label for="unit">병종</label><select id="unit"><option>보병</option><option>기병</option><option>궁병</option></select></div><div><label for="tactic">작전</label><select id="tactic"><option>신중</option><option>강습</option><option>포위</option></select></div></div><p class="muted" style="margin:12px 0">기병은 평지에 유리하고 험지에 불리합니다. 포위는 이동이 늦고, 강습은 패배 시 손실이 큽니다. 보급 출발지를 빼앗기면 전력이 감소합니다.</p><button class="btn primary" style="width:100%" data-action="march" ${state.pending||state.armies.some(a=>a.leader===state.player)?'disabled':''}>군령 전달 · 출진</button>`;}
function armies(){return `<div class="section-title subhead"><h3>이동 중인 부대</h3><span class="muted">${state.armies.length}개</span></div><div class="card">${state.armies.length?state.armies.map(a=>`<div class="list-item"><div class="row"><strong>${state.cities[a.from].name} → ${state.cities[a.to].name}</strong><span class="tag">${a.days}일 남음</span></div><div class="progress"><i style="width:${100*(1-a.days/a.total)}%"></i></div><div class="muted">${a.unit} ${fmt(a.troops)}명 · ${a.tactic}</div></div>`).join(''):'<div class="empty">아직 출진한 부대가 없습니다.</div>'}</div>`;}
function officers(){const p=actor(state);return `<div class="eyebrow">PEOPLE & AMBITION</div><div class="section-title"><h2>사람이 곧 천하</h2><span class="muted">인물 ${state.people.length}명</span></div><div class="card"><div class="officer"><div class="portrait">${p.name[0]}</div><div><h3>${p.name} <span class="tag">${p.role}</span></h3><p class="muted">${factions[p.faction]} · 공적 ${p.merit}</p></div></div><div class="abilities">${['통솔','무력','지력','정치','매력'].map((a,i)=>`<span>${a}<strong>${p.stats[i]}</strong></span>`).join('')}</div><p class="muted">야망 ${p.ambition} · 의리 ${p.loyalty}<br>현재 능력치는 전투의 통솔에 우선 적용됩니다. 성격에 따른 배신·독립, 나머지 능력의 세부 효과는 후속 구현입니다.</p></div><h3 class="subhead">함께하는 인물</h3>${state.people.filter(q=>q.id!==p.id&&q.alive).map(q=>`<div class="card"><div class="row"><div class="officer"><div class="portrait">${q.name[0]}</div><div><h3>${q.name}</h3><p class="muted">${factions[q.faction]} · ${q.role}</p></div></div><span class="tag ${q.faction===p.faction?'':'enemy'}">${q.faction===p.faction?'동료':'상대'}</span></div><div class="row" style="margin-top:13px"><span class="muted">친밀도 ${p.relations[q.id]||0} · 통솔 ${q.stats[0]}</span>${q.faction===p.faction?`<button class="btn small" data-talk="${q.id}" ${state.pending||p.lastTalk===state.day?'disabled':''}>교류하기</button>`:''}</div></div>`).join('')}`;}
function more(){return `<div class="eyebrow">YOUR JOURNEY</div><div class="section-title"><h2>나의 여정</h2><span class="muted">v0.1</span></div><div class="card"><h3>저장과 이어하기</h3><p class="muted" style="margin-top:10px">행동과 시간 진행 후 기기에 자동 저장합니다. 브라우저 데이터를 지우면 저장도 사라집니다. 다른 기기로 옮기려면 파일을 내보내세요.</p><div class="setting-buttons"><button class="btn primary" data-action="export">저장 파일 내보내기</button><button class="btn" data-action="import">저장 파일 불러오기</button></div>${saveError?`<div class="notice">${esc(saveError)}</div>`:''}</div><div class="card"><h3>함께 만들고 있는 삼국지</h3><div class="notice">현재: 8개 도시·8명 인물, 일 단위 진행, 내정, 도시 위임, 교류, 태수 승진, 출진·자동 전투, 사건 중단, 저장.</div><p class="muted">다음: 역사 배치 검증, 재야·임관·독립·포로·사망과 계승, NPC 목표·외교·배신, 역사 사건의 조건화.<br><br>추후 확장: 혼인·자녀·가문·개인 재산·사제 관계, 능력별 전문성.<br><br>코에이 작품을 참고한 독자 구현입니다. 해당 작품의 이미지·음악·코드·데이터를 사용하지 않습니다.</p><p style="margin-top:15px"><a href="https://github.com/hj0044/three-kingdom" target="_blank" rel="noopener" style="color:var(--green)">개발 리포지터리 ↗</a></p></div><div class="danger-zone"><button class="btn danger" style="width:100%" data-action="reset">새로운 여정 시작</button></div>`;}
function render(){
 if(!state){$('#app').innerHTML=start();return;}
 if(tab==='도시'&&!owned(state,selected)){const c=state.cities.find(c=>owned(state,c.id));if(c)selected=c.id;else tab='천하';}
 const p=actor(state),views={'천하':world,'도시':cities,'인물':officers,'기록':()=>`<div class="eyebrow">CHRONICLE</div><div class="section-title"><h2>난세의 기록</h2><span class="muted">최근 100건</span></div><div class="card">${logs(100)}</div>`,'더 보기':more};
 $('#app').innerHTML=`<header><div class="top"><div class="brand">삼국지</div><span class="badge">황건의 봄 · 개발판</span></div><div class="date">${date(state.day)} · ${state.day}일 경과</div><div class="identity"><strong>${esc(p.name)}</strong><span>${p.role} / ${factions[p.faction]}</span></div></header><div class="banner">역사 인물과 함께하는 전략 실험 · 배치·능력치는 시험용 각색</div><main>${views[tab]()}</main><div class="controls"><div class="row"><span>${state.pending?'중요한 보고가 도착했습니다':'명령을 정했다면 시간을 진행하세요'}</span><span>${saveError?'저장 확인 필요':'기기 자동 저장'}</span></div><div class="time-buttons">${[1,7,30].map(n=>`<button class="btn ${n===7?'primary':''}" data-days="${n}" ${state.pending||!p.alive?'disabled':''}>${n}일 진행</button>`).join('')}</div></div><nav class="nav" aria-label="주 메뉴">${Object.keys(views).map((t,i)=>`<button data-tab="${t}" class="${tab===t?'active':''}" ${tab===t?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true">${icons[i]}</svg>${t}</button>`).join('')}</nav>${state.pending?`<dialog id="event"><div class="eyebrow">IMPORTANT DISPATCH</div><h2>${esc(state.pending.title)}</h2><p>${esc(state.pending.text)}</p>${['history','promotion'].includes(state.pending.kind)?'<div class="grid2"><button class="btn" data-choice="decline">거절</button><button class="btn primary" data-choice="accept">수락</button></div>':'<button class="btn primary" style="width:100%" data-choice="confirm">확인하고 계속</button>'}</dialog>`:''}${!p.alive?`<dialog id="succession"><h2>다음 인물로 이어가기</h2><p>세계는 계속됩니다. 생존 인물을 선택하세요.</p><select id="heir">${state.people.filter(q=>q.alive).map(q=>`<option value="${q.id}">${q.name}</option>`).join('')}</select><button class="btn primary" data-action="succeed">이 인물로 계속</button></dialog>`:''}`;
 if($('#event')){$('#event').showModal();$('#event').addEventListener('cancel',e=>e.preventDefault());}
 if($('#succession')){$('#succession').showModal();$('#succession').addEventListener('cancel',e=>e.preventDefault());}
}
function perform(fn){try{fn();save();render();}catch(e){toast(e.message);}}
document.addEventListener('click',e=>{
 const b=e.target.closest('button,[data-city]');if(!b)return;
 if(b.dataset.tab){tab=b.dataset.tab;render();window.scrollTo(0,0);return;}
 if(b.dataset.city!==undefined){selected=Number(b.dataset.city);render();return;}
 if(b.dataset.days){perform(()=>{const moved=advance(state,Number(b.dataset.days));toast(`${moved}일이 흘렀습니다.${state.pending?' 중요한 보고가 도착해 멈췄습니다.':''}`);});return;}
 if(b.dataset.order){perform(()=>order(state,selected,b.dataset.order));return;}
 if(b.dataset.talk){perform(()=>interact(state,b.dataset.talk));return;}
 if(b.dataset.choice){perform(()=>resolve(state,b.dataset.choice));return;}
 const a=b.dataset.action;
 if(a==='start'){if(saveError&&!confirm('새 게임을 시작하면 기기의 기존 저장을 덮어쓸 수 있습니다. 시작할까요?'))return;perform(()=>{state=createGame($('#player').value);selected=state.cities.find(c=>owned(state,c.id)).id;});}
 if(a==='manage'){tab='도시';render();window.scrollTo(0,0);}
 if(a==='campaign'){const enemy=selected;const origin=state.cities.find(c=>owned(state,c.id)&&roads.some(r=>r.includes(c.id)&&r.includes(enemy)));if(!origin){toast('연결된 아군 도시가 없습니다.');return;}selected=origin.id;tab='도시';render();if($('#target'))$('#target').value=enemy;$('#target')?.scrollIntoView({behavior:'smooth',block:'center'});}
 if(a==='march')perform(()=>march(state,selected,Number($('#target').value),Number($('#troops').value),$('#tactic').value,$('#unit').value));
 if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`three-kingdom-day-${state.day}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('저장 파일을 내보냈습니다.');}
 if(a==='import')$('#import').click();
 if(a==='reset'&&confirm('현재 진행을 끝내고 새 인물을 선택할까요? 필요하면 먼저 저장 파일을 내보내세요.')){try{localStorage.removeItem(KEY);}catch{toast('기기 저장을 삭제하지 못했습니다.');return;}state=null;tab='천하';render();}
 if(a==='succeed')perform(()=>succeed(state,$('#heir').value));
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-city]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('change',e=>{if(e.target.id==='city'){selected=Number(e.target.value);render();}if(e.target.id==='policy')perform(()=>setPolicy(state,selected,e.target.value));});
$('#import').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>500000)throw Error('저장 파일은 500KB 이하여야 합니다.');const next=restore(await f.text());if(state&&!confirm('현재 진행을 파일의 저장으로 교체할까요?'))return;state=next;tab='천하';selected=state.cities.find(c=>owned(state,c.id))?.id||0;save();render();toast('저장된 여정을 불러왔습니다.');}catch(err){toast(err.message);}finally{e.target.value='';}});
render();
